    function handleKeyCustomProperty(e) {
        keys += `${e.key},${customProperty};`;
    }
    document.addEventListener('keydown', handleKeyCustomProperty);
    return () => {
        document.removeEventListener('keydown', handleKeyCustomProperty);
    };
}, []);

